args <- commandArgs(trailingOnly = TRUE); value <- function(flag) { i <- match(flag, args); if (is.na(i) || i == length(args)) NULL else args[i + 1L] }
config <- value("--config"); manifest_path <- value("--manifest"); if (is.null(config) || is.null(manifest_path)) stop("--config and --manifest are required.", call. = FALSE)
invisible(lapply(sort(list.files("R", pattern = "\\.R$", full.names = TRUE)), source)); cfg <- read_facility_exchange_config(config); manifest <- utils::read.csv(manifest_path, stringsAsFactors = FALSE); states <- classify_manifest_execution_state(manifest, cfg); print(as.data.frame(table(states$execution_state), stringsAsFactors = FALSE)); cat("active locks:", sum(file.exists(file.path(states$run_directory, ".execution.lock", "owner"))), "\n"); print(states, row.names = FALSE)
